import { declaredConfig } from '../../declared-config.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));

// The endpoint's source, in the pack above this task. One canonical spelling of the
// path; nothing else here names the file.
export const SOURCE = resolve(HERE, '../../oauth-exchange.mjs');

const API = 'https://api.cloudflare.com/client/v4';

// The name the worker is deployed under, and so the first label of its URL. A
// deployment that wants a different one says `workerName`; every other deployment
// gets this, because one owner runs one exchange endpoint for every dashboard they
// publish and it needs no per-repo identity.
export const DEFAULT_WORKER_NAME = 'claudinite-oauth-exchange';

// The Workers runtime behaviour this script is written against. Pinned, and pinned
// PAST rather than at today: a compatibility date is a promise that later
// backwards-incompatible runtime fixes will not reach this worker, so it is a
// property of the code, not of when the deploy ran. The endpoint uses `fetch`,
// `Request`/`Response` and `URL` and nothing dated beyond them.
export const COMPATIBILITY_DATE = '2024-01-01';

// A park the operator can act on, in the executor's own vocabulary: the last marker
// printed decides the lane, and `action` means something outside the code must
// change before this can run.
export class NeedsAction extends Error {}

const originOf = (url) => { try { return new URL(url).origin; } catch { return null; } };

// WHICH PAGE ORIGINS MAY SPEND THIS APP'S IDENTITY. Three sources, narrowest first,
// because the answer is a security boundary and a wrong guess is a stranger's site
// minting tokens against your app:
//   allowedOrigins — stated by the declaration; a custom domain has no other source
//   redirectUri    — the deployed page, whose origin is by definition allowed
//   the repo owner — `https://<owner>.github.io`, which is every project Pages site
//                    that owner publishes, and the ordinary case
// Never a wildcard and never derived from the request: the endpoint checks this list
// in its own handler precisely because CORS binds browsers and nothing else.
export function resolveOrigins(cfg, repoSlug) {
  const stated = Array.isArray(cfg.allowedOrigins) ? cfg.allowedOrigins
    : typeof cfg.allowedOrigins === 'string' ? cfg.allowedOrigins.split(',') : [];
  const origins = stated.map((o) => originOf(String(o).trim())).filter(Boolean);
  if (origins.length) return origins;

  const fromRedirect = cfg.redirectUri ? originOf(cfg.redirectUri) : null;
  if (fromRedirect) return [fromRedirect];

  const owner = String(repoSlug ?? '').split('/')[0];
  if (owner) return [`https://${owner.toLowerCase()}.github.io`];
  return [];
}

async function cf(token, path, { method = 'GET', body, headers = {} } = {}) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: { authorization: `Bearer ${token}`, ...headers },
    body,
  });
  let json = null;
  try { json = await res.json(); } catch { /* a body that is not JSON is reported by status alone */ }
  // BOTH halves. Cloudflare answers some refusals 200 with `success: false`, so the
  // status alone is not the verdict — and a transport-level failure carries no
  // `success` field at all, so the body alone is not either.
  if (!res.ok || json?.success !== true) {
    const detail = (json?.errors ?? []).map((e) => `${e.code}: ${e.message}`).join('; ')
      || `HTTP ${res.status}`;
    const err = new Error(`${method} ${path} — ${detail}`);
    err.status = res.status;
    throw err;
  }
  return json.result;
}

// The upload: the whole script and the whole binding set in one PUT. `bindings` is
// declarative and replaces what the worker had, so a binding dropped from this list
// is dropped from the deployment — which is what keeps a rotated secret from
// sitting beside a stale one.
export function uploadForm(source, { clientId, clientSecret, origins }, { FormDataImpl = FormData, BlobImpl = Blob } = {}) {
  const filename = 'oauth-exchange.mjs';
  const form = new FormDataImpl();
  form.append('metadata', JSON.stringify({
    main_module: filename,
    compatibility_date: COMPATIBILITY_DATE,
    bindings: [
      // Public by nature — the client id is in the page's own config and in every
      // authorize URL — so it is plain text rather than a secret pretending.
      { type: 'plain_text', name: 'GITHUB_CLIENT_ID', text: clientId },
      { type: 'plain_text', name: 'ALLOWED_ORIGINS', text: origins.join(',') },
      { type: 'secret_text', name: 'GITHUB_CLIENT_SECRET', text: clientSecret },
    ],
  }));
  form.append(filename, new BlobImpl([source], { type: 'application/javascript+module' }), filename);
  return form;
}

// Prove the deployed URL is actually serving this endpoint, by the two answers only
// this code gives: a disallowed origin is refused, and an allowed one with no code
// is a bad request. Together they show the route is live, the handler is ours, and
// the origin allowlist is the one just uploaded — none of which the upload's own
// 200 says. A fresh route takes a few seconds to propagate, so a miss is retried
// before it is believed.
export async function probe(url, allowedOrigin, { fetchImpl = fetch, attempts = 6, waitMs = 5000, sleep = (ms) => new Promise((r) => setTimeout(r, ms)) } = {}) {
  const post = (origin) => fetchImpl(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Origin: origin },
    body: '{}',
  });
  let last = 'never answered';
  for (let i = 0; i < attempts; i += 1) {
    if (i) await sleep(waitMs);
    try {
      const stranger = await post('https://claudinite-deploy-probe.invalid');
      const strangerBody = await stranger.json().catch(() => ({}));
      if (stranger.status !== 403 || strangerBody.error !== 'origin_not_allowed') {
        last = `a disallowed origin got HTTP ${stranger.status} ${JSON.stringify(strangerBody)}, expected 403 origin_not_allowed`;
        continue;
      }
      const ours = await post(allowedOrigin);
      const oursBody = await ours.json().catch(() => ({}));
      if (ours.status !== 400 || oursBody.error !== 'missing_code') {
        last = `${allowedOrigin} got HTTP ${ours.status} ${JSON.stringify(oursBody)}, expected 400 missing_code`;
        continue;
      }
      return { ok: true, attempts: i + 1 };
    } catch (e) {
      last = e.message;
    }
  }
  return { ok: false, why: last };
}

export async function deploy({ repoRoot, env = process.env, dryRun = false, log = console.log, fetchImpl = fetch } = {}) {
  const cfg = await declaredConfig(repoRoot);
  const repoSlug = env.CLAUDINITE_REPO || env.GITHUB_REPOSITORY || '';

  const accountId = env.CLOUDFLARE_ACCOUNT_ID?.trim();
  const apiToken = env.CLOUDFLARE_API_TOKEN?.trim();
  const clientSecret = env.GITHUB_OAUTH_CLIENT_SECRET?.trim();
  const clientId = String(cfg.clientId ?? '').trim();

  // The three things this cannot invent, each named on its own: a combined "not
  // configured" tells the operator to go and look rather than what to set.
  if (!clientId) {
    throw new NeedsAction('the declaration\'s claudinite-dashboard config has no `clientId` — '
      + 'register the GitHub App first and put its client id there; the endpoint is minted for one app');
  }
  const origins = resolveOrigins(cfg, repoSlug);
  if (!origins.length) {
    throw new NeedsAction('no page origin could be resolved — set `allowedOrigins` (or `redirectUri`) '
      + 'in the declaration\'s claudinite-dashboard config to the exact origin the dashboard is served from');
  }

  const name = String(cfg.workerName ?? DEFAULT_WORKER_NAME).trim();
  const source = await readFile(SOURCE, 'utf8');

  log(`deploying ${name} for client id ${clientId}`);
  log(`  origins allowed to call it: ${origins.join(', ')}`);

  if (dryRun) {
    log('dry run — nothing was uploaded');
    return { dryRun: true, name, origins, clientId };
  }
  if (!accountId || !apiToken || !clientSecret) {
    const missing = [
      !apiToken && 'CLOUDFLARE_API_TOKEN',
      !accountId && 'CLOUDFLARE_ACCOUNT_ID',
      !clientSecret && 'GITHUB_OAUTH_CLIENT_SECRET',
    ].filter(Boolean);
    throw new NeedsAction(`set the repo Actions secret(s): ${missing.join(', ')}`);
  }

  const call = (path, opts) => cf(apiToken, path, opts);

  // The account's workers.dev subdomain, which is the second label of every worker
  // URL it hosts. An account that has never claimed one has no URL to give.
  const { subdomain } = await call(`/accounts/${accountId}/workers/subdomain`);
  if (!subdomain) {
    throw new NeedsAction('this Cloudflare account has no workers.dev subdomain — '
      + 'claim one in the dashboard (Workers & Pages → Subdomain) and re-run');
  }

  await call(`/accounts/${accountId}/workers/scripts/${encodeURIComponent(name)}`, {
    method: 'PUT',
    body: uploadForm(source, { clientId, clientSecret, origins }),
  });
  log('  uploaded');

  // Routing is a separate fact from the code: a worker with no workers.dev route
  // uploads cleanly and answers nothing. Previews stay off — a preview URL is a
  // second origin able to mint tokens, which is exactly what the allowlist exists
  // to prevent.
  await call(`/accounts/${accountId}/workers/scripts/${encodeURIComponent(name)}/subdomain`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ enabled: true, previews_enabled: false }),
  });

  const url = `https://${name}.${subdomain}.workers.dev`;
  log(`  routed at ${url}`);

  const verdict = await probe(url, origins[0], { fetchImpl });
  if (!verdict.ok) {
    // A deployed-but-not-answering endpoint is a failure of this run, not a park:
    // the upload landed and something about the deployment is wrong, which is a
    // trace to read rather than a setting to change.
    throw new Error(`${url} did not answer as the exchange endpoint — ${verdict.why}`);
  }
  log(`  verified live (refuses a stranger's origin, accepts ${origins[0]})`);

  return { name, url, origins, clientId, exchangeUrl: cfg.exchangeUrl ?? null };
}

// What is left to do, said in full rather than as "now configure it": the endpoint
// is live from the moment it deploys, but the button appears only once the
// declaration names it, and that edit is the member's own file.
export function wiringNote({ url, exchangeUrl }) {
  if (exchangeUrl === url) return `\`exchangeUrl\` already names ${url} — sign-in is fully wired.`;
  return `NOT YET WIRED: set \`exchangeUrl\` to ${url} in this repo's `
    + `\`.claudinite-settings.json\`, on the claudinite-dashboard entry's \`config\`${exchangeUrl ? ` (it currently names ${exchangeUrl})` : ''}. `
    + 'Until it does, the page renders the token box and no Sign in button.';
}

export async function main({ argv = process.argv, env = process.env, log = console.log } = {}) {
  const arg = (n) => { const i = argv.indexOf(`--${n}`); return i === -1 ? undefined : argv[i + 1]; };
  const repoRoot = resolve(arg('root') ?? env.CLAUDINITE_REPO_ROOT ?? process.cwd());
  const result = await deploy({ repoRoot, env, dryRun: argv.includes('--dry-run'), log });
  if (!result.dryRun) log(wiringNote(result));
  return result;
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  main().catch((e) => {
    console.error(e instanceof NeedsAction
      ? `claudinite-needs-human: action — ${e.message}`
      : `deploy-oauth-exchange failed: ${e.stack ?? e.message}`);
    process.exit(1);
  });
}
SCRIPT
node --check packs/claudinite-dashboard/tasks/deploy-oauth-exchange/deploy.mjs 2>&1 | head -3; echo ok

cat > packs/claudinite-dashboard/tasks/deploy-oauth-exchange/worker.mjs <<'EOF'
// The deploy-oauth-exchange code-work entry point — the script the executor runs as
// `node worker.mjs` (cwd = this task dir, bounded by code_work_timeout).
//
// It holds no deployment logic. That is `deploy.mjs`, its sibling, which is also the
// hand-runnable script an operator uses outside the queue; this only invokes it and
// turns a throw into the exit code the executor reads.

import { pathToFileURL } from 'node:url';
import { main as runDeploy, NeedsAction } from './deploy.mjs';

const item = process.env.CLAUDINITE_ITEM || '';
const log = (s) => console.log(`deploy-oauth-exchange${item ? ` [#${item}]` : ''}: ${s}`);

export async function main() {
  await runDeploy({ log });
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  main().catch((e) => {
    // The kind routes the human-facing instruction on the parked item: a missing
    // secret or an unregistered app is a setting somebody changes, and a
    // deploy that broke is a trace somebody reads.
    console.error(e instanceof NeedsAction
      ? `claudinite-needs-human: action — ${e.message}`
      : `deploy-oauth-exchange failed: ${e.stack ?? e.message}`);
    process.exit(1);
  });
}
EOF
cat > packs/claudinite-dashboard/tasks/deploy-oauth-exchange/task.mjs <<'EOF'
// claudinite-dashboard task: deploy-oauth-exchange — put the dashboard's sign-in
// endpoint live, and prove the deployed URL answers.
//
// `frequency: 'manual'` — nothing recurring is being asked. The endpoint changes
// when its source changes, when the app's client secret is rotated, or when the set
// of page origins allowed to call it changes; none of those is a cadence, so the
// scheduler never instantiates this and the only way it runs is a work item created
// by hand:
//
//   create-work-item claudinite-dashboard/deploy-oauth-exchange
//
// `agent_model: 'none'` — pure code. Read the endpoint's source out of the mount,
// upload it with its bindings, route it, probe it, report the URL.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'deploy-oauth-exchange',
  frequency: 'manual',
  precondition_signals: [],
  agent_model: 'none',
  // It writes nothing in this repo. The one edit the deployment implies — naming
  // the minted URL as `exchangeUrl` — is the member's own declaration, and the run
  // reports it rather than making it.
  expected_outcome: 'none',
  code_work: 'node worker.mjs',
  // Three API calls and a probe that waits out route propagation (six attempts,
  // five seconds apart). The bound is that probe's worst case with room around it.
  code_work_timeout: 300,
  // The three things a public declaration must not carry. CLOUDFLARE_API_TOKEN
  // needs exactly one grant — Account · Workers Scripts · Edit — on the account
  // that hosts the endpoint; GITHUB_OAUTH_CLIENT_SECRET is the App's client secret,
  // and its client id is public and lives in the declaration instead.
  required_secrets: ['CLOUDFLARE_API_TOKEN', 'CLOUDFLARE_ACCOUNT_ID', 'GITHUB_OAUTH_CLIENT_SECRET'],

  // Never due on its own: an item exists only because somebody created one, and
  // that IS the request. A `false` here would close the operator's own item without
  // running it, with no anchor to roll to.
  precondition() {
    return { run: true, reason: 'a work item for this manual lever exists, which is the request to deploy' };
  },
};
EOF
echo ok

cat > packs/claudinite-dashboard/test/tasks/deploy-oauth-exchange/deploy.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { readFile } from 'node:fs/promises';
import {
  SOURCE, DEFAULT_WORKER_NAME, COMPATIBILITY_DATE, NeedsAction,
  resolveOrigins, uploadForm, probe, deploy, wiringNote,
} from '../../../tasks/deploy-oauth-exchange/deploy.mjs';

const member = (config) => {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-deploy-'));
  writeFileSync(join(root, '.claudinite-settings.json'),
    JSON.stringify({ packs: [{ id: 'claudinite-dashboard', config }] }, null, 2));
  return root;
};

const ENV = {
  CLOUDFLARE_API_TOKEN: 'cf-token',
  CLOUDFLARE_ACCOUNT_ID: 'acct',
  GITHUB_OAUTH_CLIENT_SECRET: 'shh',
  CLAUDINITE_REPO: 'missingbulb/Shepherd',
};

test('the endpoint source the deploy uploads is the pack\'s own, and is the real handler', async () => {
  const src = await readFile(SOURCE, 'utf8');
  assert.match(src, /export default \{/);
  assert.match(src, /login\/oauth\/access_token/);
});

test('resolveOrigins prefers the stated list, then redirectUri, then the owner\'s Pages host', () => {
  assert.deepEqual(resolveOrigins({ allowedOrigins: ['https://dash.example.com/x'] }, 'o/r'), ['https://dash.example.com']);
  assert.deepEqual(resolveOrigins({ allowedOrigins: 'https://a.example, https://b.example' }, 'o/r'),
    ['https://a.example', 'https://b.example']);
  assert.deepEqual(resolveOrigins({ redirectUri: 'https://missingbulb.github.io/Sheepdog/' }, 'o/r'),
    ['https://missingbulb.github.io']);
  assert.deepEqual(resolveOrigins({}, 'MissingBulb/Shepherd'), ['https://missingbulb.github.io']);
  assert.deepEqual(resolveOrigins({}, ''), []);
});

test('the upload carries the module, its name as main_module, and the three bindings — the secret as secret_text', async () => {
  const form = uploadForm('export default {};', {
    clientId: 'Iv1.abc', clientSecret: 'shh', origins: ['https://a.example', 'https://b.example'],
  });
  const metadata = JSON.parse(form.get('metadata'));
  assert.equal(metadata.main_module, 'oauth-exchange.mjs');
  assert.equal(metadata.compatibility_date, COMPATIBILITY_DATE);
  assert.ok(form.get('oauth-exchange.mjs'), 'the module part is named as main_module names it');
  const byName = Object.fromEntries(metadata.bindings.map((b) => [b.name, b]));
  assert.equal(byName.GITHUB_CLIENT_SECRET.type, 'secret_text');
  assert.equal(byName.GITHUB_CLIENT_ID.type, 'plain_text');
  assert.equal(byName.ALLOWED_ORIGINS.text, 'https://a.example,https://b.example');
});

test('the probe accepts only the two answers this endpoint gives, and retries while a route propagates', async () => {
  const answers = [];
  const fetchImpl = async (_url, opts) => {
    const origin = opts.headers.Origin;
    const reply = answers.shift();
    if (reply === 'down') return { status: 404, json: async () => ({}) };
    return origin === 'https://ok.example'
      ? { status: 400, json: async () => ({ error: 'missing_code' }) }
      : { status: 403, json: async () => ({ error: 'origin_not_allowed' }) };
  };
  answers.push('down');
  const v = await probe('https://w.example', 'https://ok.example', { fetchImpl, waitMs: 0, attempts: 3 });
  assert.deepEqual(v, { ok: true, attempts: 2 });

  // A URL that answers 200 to a stranger is NOT this endpoint, however alive it is.
  const permissive = async () => ({ status: 200, json: async () => ({ access_token: 'x' }) });
  const bad = await probe('https://w.example', 'https://ok.example', { fetchImpl: permissive, waitMs: 0, attempts: 2 });
  assert.equal(bad.ok, false);
  assert.match(bad.why, /origin_not_allowed/);
});

test('a missing clientId, an unresolvable origin and a missing secret are each a NeedsAction naming what to set', async () => {
  const noId = member({});
  await assert.rejects(deploy({ repoRoot: noId, env: ENV }), (e) => e instanceof NeedsAction && /clientId/.test(e.message));

  const noOrigin = member({ clientId: 'Iv1.abc' });
  await assert.rejects(deploy({ repoRoot: noOrigin, env: { ...ENV, CLAUDINITE_REPO: '' } }),
    (e) => e instanceof NeedsAction && /allowedOrigins/.test(e.message));

  const ok = member({ clientId: 'Iv1.abc' });
  await assert.rejects(deploy({ repoRoot: ok, env: { ...ENV, CLOUDFLARE_API_TOKEN: '' } }),
    (e) => e instanceof NeedsAction && /CLOUDFLARE_API_TOKEN/.test(e.message));
  for (const r of [noId, noOrigin, ok]) rmSync(r, { recursive: true, force: true });
});

test('a dry run resolves everything and uploads nothing', async () => {
  const root = member({ clientId: 'Iv1.abc' });
  const out = await deploy({ repoRoot: root, env: ENV, dryRun: true, log: () => {} });
  assert.deepEqual(out, { dryRun: true, name: DEFAULT_WORKER_NAME, origins: ['https://missingbulb.github.io'], clientId: 'Iv1.abc' });
  rmSync(root, { recursive: true, force: true });
});

test('the wiring note names the value to set, and says so is already set when it is', () => {
  assert.match(wiringNote({ url: 'https://w.example', exchangeUrl: null }), /NOT YET WIRED.*https:\/\/w\.example/s);
  assert.match(wiringNote({ url: 'https://w.example', exchangeUrl: 'https://old.example' }), /currently names https:\/\/old\.example/);
  assert.match(wiringNote({ url: 'https://w.example', exchangeUrl: 'https://w.example' }), /already names/);
});
